#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_gt_tensor.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

// Type category enum (must match kernel side)
// 0=FP32, 1=FP16, 2=BF16, 3=FP64, 4=INT8, 5=UINT8/BOOL, 6=INT16, 7=INT32, 8=INT64
static int64_t getTypeCategory(at::ScalarType dtype) {
    switch (dtype) {
        case at::kFloat:   return 0;
        case at::kHalf:    return 1;
        case at::kBFloat16: return 2;
        case at::kDouble:  return 3;
        case at::kChar:    return 4;  // int8
        case at::kByte:    return 5;  // uint8
        case at::kBool:    return 5;  // bool (stored as uint8)
        case at::kShort:   return 6;  // int16
        case at::kInt:     return 7;  // int32
        case at::kLong:    return 8;  // int64
        default:
            TORCH_CHECK(false, "gt_tensor: unsupported dtype ", dtype);
            return -1;
    }
}

// Buffer coefficient based on type category
static int64_t getBufferCoefficient(int64_t typeCategory) {
    switch (typeCategory) {
        case 0: return 28;  // fp32, CT=float
        case 1: return 20;  // fp16, CT=float
        case 2: return 20;  // bf16, CT=float
        case 3: return 44;  // fp64, CT=float
        case 4: return 16;  // int8, CT=int32
        case 5: return 16;  // uint8/bool, CT=int32
        case 6: return 20;  // int16, CT=int32
        case 7: return 28;  // int32, CT=int32
        case 8: return 44;  // int64, CT=float
        default: return 28;
    }
}

at::Tensor gt_tensor(const at::Tensor &self, const at::Tensor &other)
{
    // ---- Handle uint16/32/64: cast to float32 (per reference model) ----
    at::Tensor selfProc = self;
    at::Tensor otherProc = other;
    if (self.scalar_type() == at::kUInt16 || self.scalar_type() == at::kUInt32 ||
        self.scalar_type() == at::kUInt64 ||
        other.scalar_type() == at::kUInt16 || other.scalar_type() == at::kUInt32 ||
        other.scalar_type() == at::kUInt64) {
        selfProc = self.to(at::kFloat).contiguous();
        otherProc = other.to(at::kFloat).contiguous();
    }

    // ---- Broadcasting ----
    std::vector<int64_t> outputShape = at::infer_size(selfProc.sizes(), otherProc.sizes());
    auto selfExpanded = selfProc.expand(outputShape).contiguous();
    auto otherExpanded = otherProc.expand(outputShape).contiguous();

    // ---- Create output tensor (bool) ----
    auto output = at::empty(outputShape,
        at::TensorOptions().dtype(at::kBool).device(self.device()));

    int64_t totalLength = output.numel();
    if (totalLength == 0) {
        return output;
    }

    // ---- dtype info ----
    int64_t dtypeSize = selfExpanded.element_size();
    int64_t typeCategory = getTypeCategory(selfExpanded.scalar_type());

    // ---- Get hardware parameters ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block-level tiling (inter-core split, Cache Line aligned) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;
    if (tailLength <= 0) {
        formerNum = usedCoreNum;
        formerLength = (totalLength + formerNum - 1) / formerNum;
        tailLength = 0;
    }

    // ---- UB-level tiling (intra-core split) ----
    // tileLength must be 64-aligned (in elements) for 256B Compare API alignment
    // CT is always 4 bytes, so 256B / 4B = 64 CT elements
    int64_t bufferCoefficient = getBufferCoefficient(typeCategory);
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 64;  // must be multiple of 64 for 256B Compare alignment
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength <= 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(gt_tensor, blockDim,
                    selfExpanded, otherExpanded, output,
                    formerNum, formerLength, tailLength, tileLength,
                    typeCategory);

    return output;
}

}  // namespace ascend_kernel
