from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "gt_tensor_ext*")

# Priority: whl import (triggers TORCH_LIBRARY registration)
try:
    import gt_tensor_ext  # noqa: F401
except ImportError:
    # Fallback: direct .so loading
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """
    Element-wise greater-than comparison using AscendC kernel.
    torch.gt(input, other) -> Tensor (bool)
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
        # uint16/32/64 → float32 handled inside the kernel host
        return torch.ops.npu.gt_tensor(x, y)
