#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

/**
 * Kernel for element-wise greater-than comparison.
 * Host pre-casts all input types to float32 before calling this kernel.
 * Output is int16_t (0/1) which host converts to bool.
 */
class KernelGtTensor {
public:
    __aicore__ inline KernelGtTensor() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR output,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ float *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ float *)y + offset, formerLength);
            outGm.SetGlobalBuffer((__gm__ int16_t *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ float *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ float *)y + offset, tailLength);
            outGm.SetGlobalBuffer((__gm__ int16_t *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(int16_t));

        // Float buffers for aligned comparison (used as padding targets)
        pipe.InitBuffer(padBufX, tileLength * sizeof(float));
        pipe.InitBuffer(padBufY, tileLength * sizeof(float));

        // Mask buffer for Compare output (bit-packed uint8_t), 32B aligned
        int64_t maskBufSize = ((tileLength + 7) / 8 + 31) / 32 * 32;
        pipe.InitBuffer(maskBuf, maskBufSize);

        // Ones buffer for Select expansion (int16_t supported by Duplicate)
        pipe.InitBuffer(onesBuf, tileLength * sizeof(int16_t));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        if (this->blockLength == 0) {
            return;
        }

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            int64_t tailIdx = tileNum - 1;
            // Align tail tile to 256 bytes for Compare API (float = 4 bytes → 64 elements)
            int64_t align256 = 64;
            int64_t alignedTailCount = ((tailTileLength + align256 - 1) / align256) * align256;
            CopyIn(tailIdx, tailTileLength);
            Compute(tailIdx, tailTileLength, alignedTailCount);
            CopyOut(tailIdx, tailTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<float> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
        inQueueX.EnQue(xLocal);

        AscendC::LocalTensor<float> yLocal = inQueueY.AllocTensor<float>();
        AscendC::DataCopyPad(yLocal, yGm[progress * this->tileLength], copyParams, padParams);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength, int64_t alignedCount)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
        AscendC::LocalTensor<float> yLocal = inQueueY.DeQue<float>();

        // Copy to pad buffers and handle tail alignment
        AscendC::LocalTensor<float> xPad = padBufX.Get<float>();
        AscendC::LocalTensor<float> yPad = padBufY.Get<float>();
        AscendC::DataCopy(xPad, xLocal, curTileLength);
        AscendC::DataCopy(yPad, yLocal, curTileLength);

        // Pad tail region for 256B alignment (required by Compare API)
        if (alignedCount > curTileLength) {
            float xPadVal = -3.402823466e+38f;  // near -inf
            float yPadVal = 3.402823466e+38f;   // near +inf
            AscendC::Duplicate(xPad[curTileLength], xPadVal, alignedCount - curTileLength);
            AscendC::Duplicate(yPad[curTileLength], yPadVal, alignedCount - curTileLength);
        }

        // Compare: x > y → bit-packed uint8_t mask
        AscendC::LocalTensor<uint8_t> maskLocal = maskBuf.Get<uint8_t>();
        AscendC::Compare(maskLocal, xPad, yPad, AscendC::CMPMODE::GT, alignedCount);

        // Expand bit-packed mask to per-element int16_t output (0 or 1)
        AscendC::LocalTensor<int16_t> onesLocal = onesBuf.Get<int16_t>();
        AscendC::Duplicate(onesLocal, static_cast<int16_t>(1), alignedCount);

        AscendC::LocalTensor<int16_t> outLocal = outQueueZ.AllocTensor<int16_t>();
        AscendC::Select(outLocal, maskLocal, onesLocal, static_cast<int16_t>(0),
                        AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, alignedCount);

        outQueueZ.EnQue<int16_t>(outLocal);
        inQueueX.FreeTensor(xLocal);
        inQueueY.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<int16_t> outLocal = outQueueZ.DeQue<int16_t>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(int16_t)), 0, 0, 0};
        AscendC::DataCopyPad(outGm[progress * this->tileLength], outLocal, copyParams);
        outQueueZ.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> padBufX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> padBufY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> onesBuf;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::GlobalTensor<int16_t> outGm;
    int64_t blockLength;
    int64_t tileLength;
};

// Kernel entry point (float32 inputs only, host handles type casting)
extern "C" __global__ __aicore__ void gt_tensor(
    GM_ADDR x, GM_ADDR y, GM_ADDR output,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength)
{
    KernelGtTensor op;
    op.Init(x, y, output, formerNum, formerLength, tailLength, tileLength);
    op.Process();
}
