#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_gt_tensor.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t BUFFER_COEFFICIENT = 31;  // float32 input + int16 output + Compare mask + ones

at::Tensor gt_tensor(const at::Tensor &self, const at::Tensor &other)
{
    // ---- Cast both inputs to float32 for unified kernel processing ----
    auto selfFloat = self.to(at::kFloat).contiguous();
    auto otherFloat = other.to(at::kFloat).contiguous();

    // ---- Broadcasting ----
    std::vector<int64_t> outputShape = at::infer_size(selfFloat.sizes(), otherFloat.sizes());
    auto selfExpanded = selfFloat.expand(outputShape).contiguous();
    auto otherExpanded = otherFloat.expand(outputShape).contiguous();

    int64_t totalLength = 1;
    for (auto dim : outputShape) {
        totalLength *= dim;
    }
    if (totalLength == 0) {
        return at::empty(outputShape,
            at::TensorOptions().dtype(at::kBool).device(self.device()));
    }

    // ---- Create int16_t intermediate output tensor ----
    auto outputInt16 = at::empty(outputShape,
        at::TensorOptions().dtype(at::kShort).device(self.device()));

    // ---- Get hardware parameters ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block-level tiling (inter-core split, Cache Line aligned) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;
    if (tailLength <= 0) {
        formerNum = usedCoreNum;
        formerLength = (totalLength + formerNum - 1) / formerNum;
        tailLength = 0;
    }

    // ---- UB-level tiling ----
    // Compare uses float (4 bytes), needs 256B alignment → 64 float elements
    int64_t maxTileElements = ubSizeLimit / BUFFER_COEFFICIENT;
    int64_t alignElements = 64;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength <= 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(gt_tensor, blockDim,
                    selfExpanded, otherExpanded, outputInt16,
                    formerNum, formerLength, tailLength, tileLength);

    // Convert int16_t (0/1) output to bool
    return outputInt16.to(at::kBool);
}

}  // namespace ascend_kernel
