from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"

# Try whl import first, fall back to direct .so loading
_loaded = False
try:
    import gt_tensor_ext  # noqa: F401
    _loaded = True
except ImportError:
    pass

if not _loaded:
    import glob as _glob
    _libs = _glob.glob(str(_KERNEL_BUILD / "gt_tensor_ext*.so"))
    if _libs:
        torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """
    Element-wise greater-than comparison using AscendC kernel.
    torch.gt(input, other) -> Tensor (bool)
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
        return torch.ops.npu.gt_tensor(x, y)
